//! Real schema3 producers and an actual frozen schema2 writer migration; no expected generated by the new encoder.
use app_core::{
    contracts::*,
    domain::{
        canonical_hash, content_hash,
        model_config::{codec::*, credentials::*},
    },
    ports::ProductRepository,
};
use app_infra::storage::{SqliteStore, http_service_identity_migration_sha256};
use rusqlite::Connection as SqlConnection;
use std::{
    collections::BTreeMap,
    path::{Path, PathBuf},
};
const OLD_SQL: &str = include_str!("fixtures/http-schema2-original.sql");
const OLD_INPUT: &str = include_str!("fixtures/http-schema2-original-input.json");
const OLD_LOADED: &str = include_str!("fixtures/http-schema2-original-loaded.json");
const OLD_MANIFEST: &str = include_str!("fixtures/http-schema2-original-manifest.json");
// Frozen schema2 fixture has the original untagged snapshot shape. Project the
// actual tagged legacy branch explicitly; a codec3 branch is a regression here.
#[derive(Debug, serde::Deserialize, PartialEq)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
struct LegacyConfigurationState {
    draft: Configuration,
    applied: Option<Configuration>,
    draft_head_revision: u32,
    applied_head_revision: u32,
    runtime_connections: Vec<ConnectionRuntimeView>,
    runtime_purposes: Vec<PurposeRuntimeView>,
}
fn legacy_document(value: ConfigurationDocument) -> Configuration {
    match value {
        ConfigurationDocument::Legacy { configuration } => configuration,
        ConfigurationDocument::ServiceGraph { .. } => {
            panic!("legacy fixture unexpectedly became codec3")
        }
    }
}
fn legacy_state(value: ConfigurationState) -> LegacyConfigurationState {
    LegacyConfigurationState {
        draft: legacy_document(value.draft),
        applied: value.applied.map(legacy_document),
        draft_head_revision: value.draft_head_revision,
        applied_head_revision: value.applied_head_revision,
        runtime_connections: value.runtime_connections,
        runtime_purposes: value.runtime_purposes,
    }
}
fn dir() -> PathBuf {
    let root = std::env::var_os("FP_STORAGE_OUTPUT")
        .map(PathBuf::from)
        .unwrap_or_else(std::env::temp_dir);
    let p = root.join(format!("http-identity-v3-{}", uuid::Uuid::new_v4()));
    std::fs::create_dir_all(&p).unwrap();
    p
}
fn command(s: &SqliteStore, id: &str, c: Command) -> CommandReceipt {
    s.dispatch(
        CommandEnvelope {
            operation_id: id.into(),
            expected_revision: None,
            command: c,
        },
        30,
    )
    .unwrap()
}
fn snapshot_rows(c: &SqlConnection) -> Vec<(String, Vec<Vec<String>>)> {
    // Freeze the original schema2 column inventory from its original SQL, not
    // the candidate schema. Additive v3/v4 columns have independent contracts.
    let original = SqlConnection::open_in_memory().unwrap();
    original.execute_batch("PRAGMA foreign_keys=OFF").unwrap();
    original.execute_batch(OLD_SQL).unwrap();
    let tables = [
        "config_heads",
        "config_revision_seals",
        "connections",
        "models",
        "model_parameters",
        "purpose_bindings",
        "binding_engines",
        "templates",
        "term_sets",
        "terms",
        "credential_refs",
        "credential_pool_revisions",
        "credential_pool_seals",
        "credential_pool_members",
    ];
    tables
        .into_iter()
        .map(|t| {
            let mut q = original
                .prepare(&format!("PRAGMA table_info({t})"))
                .unwrap();
            let cols = q
                .query_map([], |r| r.get::<_, String>(1))
                .unwrap()
                .collect::<Result<Vec<_>, _>>()
                .unwrap();
            let actual_cols = c
                .prepare(&format!("PRAGMA table_info({t})"))
                .unwrap()
                .query_map([], |r| r.get::<_, String>(1))
                .unwrap()
                .collect::<Result<Vec<_>, _>>()
                .unwrap();
            assert!(
                cols.iter().all(|column| actual_cols.contains(column)),
                "missing original column in {t}"
            );
            let columns = cols
                .iter()
                .filter(|s| {
                    !matches!(
                        s.as_str(),
                        "adapter_binding_schema"
                            | "adapter_contract_revision"
                            | "compatibility_profile_id"
                            | "compatibility_profile_revision"
                            | "provider_preset_id"
                            | "provider_preset_revision"
                            | "envelope_schema"
                    )
                })
                .map(|s| format!("quote(\"{s}\")"))
                .collect::<Vec<_>>();
            let mut q = c
                .prepare(&format!("SELECT {} FROM {t}", columns.join(",")))
                .unwrap();
            let mut rows = q
                .query_map([], |r| {
                    (0..columns.len())
                        .map(|i| r.get::<_, String>(i))
                        .collect::<rusqlite::Result<Vec<_>>>()
                })
                .unwrap()
                .collect::<Result<Vec<_>, _>>()
                .unwrap();
            rows.sort();
            (t.into(), rows)
        })
        .collect()
}
fn legacy_database(path: &Path) {
    let c = SqlConnection::open(path).unwrap();
    c.execute_batch("PRAGMA foreign_keys=OFF").unwrap();
    c.execute_batch(OLD_SQL).unwrap();
    c.execute_batch("PRAGMA foreign_keys=ON").unwrap();
    assert_eq!(
        c.query_row("SELECT max(version) FROM schema_migrations", [], |r| r
            .get::<_, i64>(0))
            .unwrap(),
        2
    );
}
#[test]
fn original_writer_schema_two_migrates_without_rewriting_old_seal_order_zero_or_null() {
    let manifest: serde_json::Value = serde_json::from_str(OLD_MANIFEST).unwrap();
    assert_eq!(
        content_hash(OLD_SQL),
        manifest["fixture_files"]["http-schema2-original.sql"]
    );
    assert_eq!(
        content_hash(OLD_INPUT),
        manifest["fixture_files"]["http-schema2-original-input.json"]
    );
    assert_eq!(
        content_hash(OLD_LOADED),
        manifest["fixture_files"]["http-schema2-original-loaded.json"]
    );
    let d = dir();
    let path = d.join("profile.sqlite3");
    legacy_database(&path);
    let c = SqlConnection::open(&path).unwrap();
    let before = snapshot_rows(&c);
    let seal: String = c
        .query_row("SELECT content_hash FROM config_revision_seals", [], |r| {
            r.get(0)
        })
        .unwrap();
    assert_eq!(seal, manifest["stored_seal"]);
    // The old wire grammar cannot encode any of the newly approved identities.
    for sql in [
        "UPDATE connections SET protocol='baidu_vip'",
        "UPDATE connections SET auth_mode='baidu_app_secret'",
        "UPDATE credential_refs SET auth_kind='baidu_app_secret'",
    ] {
        assert!(c.execute(sql, []).is_err());
    }
    drop(c);
    let before_path = d.join("before-schema2.sqlite3");
    std::fs::copy(&path, &before_path).unwrap();
    let store = SqliteStore::open(&path, "legacy-http-profile", "new-server", 100).unwrap();
    let now = legacy_state(store.snapshot().unwrap().configuration);
    let old: LegacyConfigurationState = serde_json::from_str(OLD_LOADED).unwrap();
    assert_eq!(now, old);
    assert!(now.draft.codec_version.is_none());
    assert_ne!(canonical_hash(&now.draft).unwrap(), seal);
    let c = SqlConnection::open(&path).unwrap();
    assert_eq!(snapshot_rows(&c), before);
    assert_eq!(
        c.query_row("SELECT content_hash FROM config_revision_seals", [], |r| {
            r.get::<_, String>(0)
        })
        .unwrap(),
        seal
    );
    assert_eq!(
        c.query_row(
            "SELECT version FROM schema_migrations WHERE version=3",
            [],
            |r| r.get::<_, u32>(0)
        )
        .unwrap(),
        3
    );
    assert_eq!(
        c.query_row(
            "SELECT migration_sha256 FROM schema_migrations WHERE version=3",
            [],
            |r| r.get::<_, String>(0)
        )
        .unwrap(),
        http_service_identity_migration_sha256()
    );
    assert_eq!(c.query_row("SELECT count(*) FROM connections WHERE adapter_binding_schema IS NULL AND provider_preset_id IS NULL",[],|r|r.get::<_,u32>(0)).unwrap(),2);
    assert_eq!(
        c.query_row("SELECT max(version) FROM schema_migrations", [], |r| r
            .get::<_, u32>(0))
            .unwrap(),
        5
    );
    assert_eq!(
        c.query_row(
            "SELECT migration_sha256 FROM schema_migrations WHERE version=4",
            [],
            |r| r.get::<_, String>(0)
        )
        .unwrap(),
        app_infra::storage::service_graph_migration_sha256()
    );
    let backup = d.join("profile.sqlite3.pre-v5-100.sqlite3");
    assert!(backup.is_file());
    let b = SqlConnection::open(backup).unwrap();
    assert_eq!(
        b.query_row("SELECT max(version) FROM schema_migrations", [], |r| r
            .get::<_, u32>(0))
            .unwrap(),
        2
    );
    assert_eq!(snapshot_rows(&b), before);
    drop(c);
    drop(store);
    let reopened = SqliteStore::open(&path, "legacy-http-profile", "again", 200).unwrap();
    assert_eq!(
        legacy_state(reopened.snapshot().unwrap().configuration),
        old
    );
    let after = d.join("after-schema3.sqlite3");
    reopened.backup(&after).unwrap();
    let backup = d.join("profile.sqlite3.pre-v5-100.sqlite3");
    let restored = d.join("restored-schema2.sqlite3");
    std::fs::copy(&backup, &restored).unwrap();
    emit(
        "migration",
        vec![
            proof("V3-MIGRATION", 10),
            proof("V3-LEGACY-PRESERVATION", 8),
        ],
        serde_json::json!({"directory":d,"before_fixture":"crates/app-infra/tests/fixtures/http-schema2-original.sql","before":artifact(&before_path),"after":artifact(&after),"backup":artifact(&backup),"restored":artifact(&restored),"old_seal":seal}),
    );
}
fn binding(protocol: &str) -> AdapterBinding {
    AdapterBinding {
        protocol: ProtocolKey {
            protocol_id: protocol.into(),
            contract_revision: 1,
        },
        profile: CompatibilityProfileKey {
            profile_id: "custom-text".into(),
            profile_revision: 1,
        },
    }
}
fn preset() -> StoredProviderPreset {
    StoredProviderPreset {
        key: ProviderPresetKey {
            preset_id: "user.controlled".into(),
            preset_revision: 1,
        },
        namespace: CatalogNamespace::User,
        provider_id: "user.provider".into(),
        provider_label: "Controlled".into(),
        display_name: "Controlled source".into(),
        binding: binding("openai_compatible"),
        endpoint: Some("http://127.0.0.1:1/v1".into()),
        auth_kind: "none".into(),
        options: BTreeMap::from([("temperature".into(), CatalogScalar::Number(0.0))]),
        source_refs: vec!["controlled-source".into()],
    }
}
#[test]
fn actual_codec_two_save_apply_reopen_rehash_matches_seal_and_immutable_preset() {
    let d = dir();
    let path = d.join("profile.sqlite3");
    let store = SqliteStore::open(&path, "profile", "server", 1).unwrap();
    let p = preset();
    store.store_provider_preset(p.clone(), 2).unwrap();
    store.store_provider_preset(p.clone(), 3).unwrap();
    assert_eq!(store.provider_preset(p.key.clone()).unwrap(), p);
    let mut different = p.clone();
    different.display_name = "changed".into();
    assert_eq!(
        store.store_provider_preset(different, 4).unwrap_err().code,
        "provider_preset_conflict"
    );
    let mut c: Configuration = serde_json::from_str(OLD_INPUT).unwrap();
    c.codec_version = Some(2);
    for con in &mut c.connections {
        con.adapter_binding = Some(binding(&con.protocol));
        con.preset_source = Some(p.key.clone());
    }
    let r = command(
        &store,
        "codec-two-save",
        Command::SaveConfiguration {
            configuration: c.clone(),
            expected_head_revision: 0,
        },
    );
    let id = r.result_id.unwrap();
    command(
        &store,
        "codec-two-apply",
        Command::ApplyConfiguration {
            revision_id: id.clone(),
            expected_head_revision: 0,
        },
    );
    c.revision_id = id.clone();
    let expected = normalize_service_graph_configuration(&c).unwrap();
    assert_eq!(
        store
            .snapshot()
            .unwrap()
            .configuration
            .applied
            .map(legacy_document),
        Some(expected.clone())
    );
    let bytes = encode_configuration(&c).unwrap();
    let hash = content_hash(&bytes);
    let sql = SqlConnection::open(&path).unwrap();
    assert_eq!(
        sql.query_row(
            "SELECT content_hash FROM config_revision_seals WHERE revision_id=?1",
            [&id],
            |r| r.get::<_, String>(0)
        )
        .unwrap(),
        hash
    );
    assert_eq!(
        sql.query_row(
            "SELECT codec_version FROM config_revisions WHERE revision_id=?1",
            [&id],
            |r| r.get::<_, u32>(0)
        )
        .unwrap(),
        2
    );
    drop(sql);
    drop(store);
    let store = SqliteStore::open(&path, "profile", "reopened", 50).unwrap();
    let loaded = legacy_document(store.snapshot().unwrap().configuration.applied.unwrap());
    assert_eq!(loaded, expected);
    assert_eq!(encode_configuration(&loaded).unwrap(), bytes);
    let sql = SqlConnection::open(&path).unwrap();
    assert_eq!(
        sql.query_row("SELECT count(*) FROM pragma_foreign_key_check", [], |r| r
            .get::<_, u32>(
            0
        ))
        .unwrap(),
        0
    );
    assert!(
        sql.execute("DELETE FROM provider_preset_versions", [])
            .is_err()
    );
    let snapshot = d.join("codec-schema3.sqlite3");
    store.backup(&snapshot).unwrap();
    emit(
        "codec",
        vec![proof("V3-CODEC", 7), proof("V3-PRESETS", 4)],
        serde_json::json!({"database":artifact(&snapshot),"configuration_hash":hash}),
    );
}
#[test]
fn trusted_typed_pool_metadata_cannot_select_other_kind_inactive_or_wrong_revision() {
    let d = dir();
    let store = SqliteStore::open(d.join("profile.sqlite3"), "typed", "server", 1).unwrap();
    let reference = CredentialReference {
        credential_id: "typed-id".into(),
        credential_version_id: "opaque-version".into(),
        pool_id: "typed-pool".into(),
        pool_revision: 1,
        label: "控".into(),
        masked_hint: "••".into(),
    };
    store
        .begin_credential_material(
            reference.clone(),
            CredentialStorageMetadata::EnvelopeV1 {
                kind: CredentialMaterialKind::BaiduAppSecret,
            },
            2,
        )
        .unwrap();
    assert!(
        store
            .select_credential_for_kind(
                reference.pool_id.clone(),
                1,
                CredentialMaterialKind::BaiduAppSecret
            )
            .is_err()
    );
    store
        .activate_credential(reference.credential_id.clone(), 3)
        .unwrap();
    assert_eq!(
        store
            .select_credential(reference.pool_id.clone(), 1)
            .unwrap_err()
            .code,
        "credential_kind_mismatch"
    );
    let selected = store
        .select_credential_for_kind(
            reference.pool_id.clone(),
            1,
            CredentialMaterialKind::BaiduAppSecret,
        )
        .unwrap();
    let metadata = store
        .credential_lease_metadata(
            reference.pool_id.clone(),
            1,
            selected.vault_ref.clone(),
            CredentialMaterialKind::BaiduAppSecret,
        )
        .unwrap();
    assert_eq!(
        metadata.storage,
        CredentialStorageMetadata::EnvelopeV1 {
            kind: CredentialMaterialKind::BaiduAppSecret
        }
    );
    assert_eq!(metadata.credential.credential_version_id, "opaque-version");
    assert!(
        store
            .credential_lease_metadata(
                reference.pool_id.clone(),
                2,
                selected.vault_ref.clone(),
                CredentialMaterialKind::BaiduAppSecret
            )
            .is_err()
    );
    assert!(
        store
            .credential_lease_metadata(
                reference.pool_id.clone(),
                1,
                "wrong-vault".into(),
                CredentialMaterialKind::BaiduAppSecret
            )
            .is_err()
    );
    store.revoke_credential(reference.credential_id, 4).unwrap();
    assert!(
        store
            .credential_lease_metadata(
                reference.pool_id,
                1,
                selected.vault_ref,
                CredentialMaterialKind::BaiduAppSecret
            )
            .is_err()
    );
    let snapshot = d.join("credential-schema3.sqlite3");
    store.backup(&snapshot).unwrap();
    emit(
        "credentials",
        vec![proof("V3-CREDENTIALS", 7)],
        serde_json::json!({"database":artifact(&snapshot)}),
    );
}

fn emit(case: &str, checks: Vec<serde_json::Value>, detail: serde_json::Value) {
    if let Some(output) = std::env::var_os("FP_STORAGE_OUTPUT") {
        let path = PathBuf::from(output).join("components/v3-delta");
        std::fs::create_dir_all(&path).unwrap();
        let receipt = serde_json::json!({"kind":"http_storage_v3_delta_receipt","run_id":std::env::var("FP_STORAGE_RUN_ID").unwrap(),"source_tree_sha256":std::env::var("FP_STORAGE_SOURCE_SHA256").unwrap(),"execution_nonce":std::env::var("FP_STORAGE_EXECUTION_NONCE").unwrap(),"completed_at_ms":std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_millis(),"checks":checks,"detail":detail});
        use std::io::Write;
        let mut f = std::fs::OpenOptions::new()
            .write(true)
            .create_new(true)
            .open(path.join(format!("{case}.json")))
            .unwrap();
        f.write_all(&serde_json::to_vec_pretty(&receipt).unwrap())
            .unwrap();
        f.sync_all().unwrap();
    }
}
fn proof(id: &str, assertions: u64) -> serde_json::Value {
    serde_json::json!({"id":id,"status":"passed","assertions":assertions,"skipped":0,"source":"storage_http_identity_v3::real_rust_producer_and_sqlite"})
}
enum BoundArgument {
    Sql(rusqlite::types::Value),
    Wide(i128),
}
impl rusqlite::ToSql for BoundArgument {
    fn to_sql(&self) -> rusqlite::Result<rusqlite::types::ToSqlOutput<'_>> {
        match self {
            Self::Sql(value) => rusqlite::ToSql::to_sql(value),
            Self::Wide(value) => i64::try_from(*value)
                .map(|v| rusqlite::types::ToSqlOutput::Owned(rusqlite::types::Value::Integer(v)))
                .map_err(|e| rusqlite::Error::ToSqlConversionFailure(Box::new(e))),
        }
    }
}
fn arg(value: &serde_json::Value) -> BoundArgument {
    use rusqlite::types::Value as S;
    let sql = match value {
        serde_json::Value::Null => S::Null,
        serde_json::Value::String(s) => S::Text(s.clone()),
        serde_json::Value::Bool(b) => S::Integer(i64::from(*b)),
        serde_json::Value::Number(n) => {
            if let Some(i) = n.as_i64() {
                S::Integer(i)
            } else if let Some(v) = n.as_u64() {
                return BoundArgument::Wide(i128::from(v));
            } else {
                S::Real(n.as_f64().unwrap())
            }
        }
        serde_json::Value::Object(o) if o.len() == 1 && o.contains_key("$bytes_hex") => {
            let h = o["$bytes_hex"].as_str().unwrap();
            S::Blob(
                (0..h.len())
                    .step_by(2)
                    .map(|i| u8::from_str_radix(&h[i..i + 2], 16).unwrap())
                    .collect(),
            )
        }
        serde_json::Value::Object(o) if o.len() == 1 && o.contains_key("$integer") => {
            return BoundArgument::Wide(o["$integer"].as_str().unwrap().parse().unwrap());
        }
        _ => panic!("boundary argument must be typed scalar"),
    };
    BoundArgument::Sql(sql)
}
fn insert(
    c: &SqlConnection,
    table: &str,
    row: &serde_json::Map<String, serde_json::Value>,
) -> rusqlite::Result<usize> {
    let keys = row.keys().collect::<Vec<_>>();
    let sql = format!(
        "INSERT INTO \"{table}\" ({}) VALUES ({})",
        keys.iter()
            .map(|s| format!("\"{s}\""))
            .collect::<Vec<_>>()
            .join(","),
        vec!["?"; keys.len()].join(",")
    );
    c.execute(
        &sql,
        rusqlite::params_from_iter(keys.iter().map(|k| arg(&row[*k]))),
    )
}
fn root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../..")
        .canonicalize()
        .unwrap()
}
